class AdoptionAggregatorModule:
    ...
    def update(self, mask_state: Dict[int, int], total_agents: int = None) -> float:
        total = total_agents if (total_agents is not None and total_agents > 0) else len(mask_state)
        rate = 0.0
        if total > 0:
            rate = sum(mask_state.get(aid, 0) for aid in mask_state.keys()) / float(total)
        self.history.append(rate)
        return float(np.mean(self.history)) if self.window > 1 else rate
